<script lang="ts">
	import {locale as mmLocale,t as mmT} from '$lib/i18n';
 import {onMount} from 'svelte';
 let pending=$state(false);let message=$state('');
 onMount(async()=>{try{const r=await fetch('/api/v1/settings');if(r.ok)pending=(await r.json()).connections_setup_pending;}catch{}});
 async function finish(){try{const r=await fetch('/api/v1/settings/finish-setup',{method:'POST'});if(!r.ok)throw Error();pending=false;}catch{message='Einrichtung konnte nicht abgeschlossen werden.';}}
</script>
{#if pending}<section class="space-y-3 rounded-xl border border-primary bg-card p-5"><h2 class="text-xl font-semibold">{mmT($mmLocale, "Einrichtung fortsetzen" )}</h2><p>{mmT($mmLocale, "Die Datenbank und dein Admin-Konto sind bereit. Richte jetzt die gewünschten Verbindungen ein — bestehende Downloadmanager kannst du weiterverwenden." )}</p><ol class="list-inside list-decimal space-y-2"><li><button type="button" class="underline" onclick={()=>window.dispatchEvent(new CustomEvent('mm-settings-tab',{detail:'indexers'}))}>{mmT($mmLocale, "Indexer verbinden" )}</button>{mmT($mmLocale, ": direkter NZB-Indexer oder Prowlarr/Jackett unter System." )}</li><li><button type="button" class="underline" onclick={()=>window.dispatchEvent(new CustomEvent('mm-settings-tab',{detail:'system'}))}>{mmT($mmLocale, "Downloadmanager konfigurieren" )}</button>{mmT($mmLocale, ": SABnzbd für NZB, qBittorrent oder Transmission für Torrents. Die automatisch bereitgestellten Dienste heißen sabnzbd und qbittorrent, jeweils Port 8080." )}</li><li>{mmT($mmLocale, "Bibliothekspfade prüfen und vorgemerkte Änderungen durch einen Containerneustart aktivieren." )}</li></ol><p class="text-sm text-muted-foreground">{mmT($mmLocale, "Du kannst alle Verbindungen überspringen und später ergänzen. Ohne passenden Downloadmanager werden keine Downloads gestartet. NNTP-Zugänge und Entpackungsregeln verwaltest du derzeit in SABnzbd." )}</p><button type="button" class="rounded-md bg-primary px-4 py-2 text-primary-foreground" onclick={finish}>{mmT($mmLocale, "Einrichtung abschließen / später fortsetzen" )}</button>{#if message}<p role="alert">{mmT($mmLocale, message)}</p>{/if}</section>{/if}
